#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# DRAFT, NOT YET RUN (docs/fdroid-0.9.3.md §3): builds the reduced ARM64 ONNX Runtime from source for an F-Droid build
# and publishes it as a local Maven repository that -Platentjam.reducedOrtRepo can point at. Unlike
# build_reduced_ort.py it needs no onnxruntime Python wheel: the operator list is the committed
# tools/runtime/required-operators.config, generated by build_reduced_ort.py for the shipped models.
#
#   fdroid_reduced_ort.sh ORT_SOURCE NDK SDK STOCK_AAR OUTPUT_REPO
#
# ORT_SOURCE  onnxruntime v1.26.0 checkout with submodules (an F-Droid srclib)
# NDK         Android NDK r28c (28.2.13676358)
# SDK         Android SDK root
# STOCK_AAR   onnxruntime-android-1.26.0.aar from Maven Central: the Java classes and the other ABIs come from it
# OUTPUT_REPO directory for the local Maven repository (created)
set -euo pipefail

ORT_SOURCE=$1 NDK=$2 SDK=$3 STOCK_AAR=$4 OUTPUT_REPO=$5
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../.." && pwd)
OPERATORS="$HERE/required-operators.config"
VERSION=1.26.0
CANDIDATE="$VERSION-latentjam-arm64"
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

[ -f "$OPERATORS" ] || { echo "missing $OPERATORS: generate it with build_reduced_ort.py" >&2; exit 2; }
[ "$(git -C "$ORT_SOURCE" describe --tags --exact-match 2>/dev/null)" = "v$VERSION" ] || { echo "ORT source is not v$VERSION" >&2; exit 2; }

# The same configuration as build_reduced_ort.py (its manifest's build_command), minus model conversion.
python3 "$ORT_SOURCE/tools/ci_build/build.py" \
  --build_dir "$WORK/native" --config Release --cmake_generator Ninja \
  --android --android_sdk_path "$SDK" --android_ndk_path "$NDK" --android_abi arm64-v8a --android_api 24 \
  --build_shared_lib --build_java --enable_lto --disable_ml_ops \
  --include_ops_by_config "$OPERATORS" --skip_tests --skip_submodule_sync --skip_pip_install \
  --cmake_extra_defines onnxruntime_BUILD_UNIT_TESTS=OFF --parallel "${JOBS:-4}"

STRIP=$(ls "$NDK"/toolchains/llvm/prebuilt/*/bin/llvm-strip | head -1)
mkdir -p "$WORK/aar"
(cd "$WORK/aar" && unzip -q "$STOCK_AAR")
for lib in libonnxruntime.so libonnxruntime4j_jni.so; do
  built=$(find "$WORK/native" -path "*arm64-v8a*" -name "$lib" -print -quit)
  [ -n "$built" ] || { echo "build produced no $lib" >&2; exit 1; }
  "$STRIP" --strip-unneeded -o "$WORK/aar/jni/arm64-v8a/$lib" "$built"
done

DEST="$OUTPUT_REPO/com/microsoft/onnxruntime/onnxruntime-android/$CANDIDATE"
mkdir -p "$DEST"
AAR="$DEST/onnxruntime-android-$CANDIDATE.aar"
# Deterministic archive: sorted entries and fixed timestamps, as build_reduced_ort.py writes its candidate.
python3 - "$WORK/aar" "$AAR" <<'PY'
import sys, zipfile
from pathlib import Path
src, out = Path(sys.argv[1]), sys.argv[2]
with zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as z:
    for p in sorted(q for q in src.rglob('*') if q.is_file()):
        info = zipfile.ZipInfo(p.relative_to(src).as_posix(), date_time=(1980, 1, 1, 0, 0, 0))
        info.external_attr = 0o644 << 16
        z.writestr(info, p.read_bytes(), zipfile.ZIP_DEFLATED)
PY
cat > "$DEST/onnxruntime-android-$CANDIDATE.pom" <<POM
<?xml version="1.0" encoding="UTF-8"?>
<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion>
<groupId>com.microsoft.onnxruntime</groupId><artifactId>onnxruntime-android</artifactId>
<version>$CANDIDATE</version><packaging>aar</packaging></project>
POM

# The manifest the Gradle check reads: the shipped models and the operator list this runtime was built for.
python3 - "$ROOT" "$OUTPUT_REPO" "$CANDIDATE" "$VERSION" "$OPERATORS" "$AAR" "$STOCK_AAR" <<'PY'
import hashlib, json, sys
from pathlib import Path
root, repo, candidate, version, operators, aar, stock = sys.argv[1:]
h = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
models = {p.name: h(p) for p in sorted(Path(root, 'androidApp/src/main/assets/ml').glob('*.onnx'))}
Path(repo, 'manifest.json').write_text(json.dumps({
    'ort_version': version, 'candidate_version': candidate, 'models': models,
    'operators_sha256': h(operators), 'candidate_aar_sha256': h(aar), 'stock_aar_sha256': h(stock),
    'custom_abis': ['arm64-v8a'], 'built_from_source': True,
}, indent=1) + '\n')
PY
echo "reduced ORT repository: $OUTPUT_REPO"
